import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';

function idOf(req: Request): string {
  const id = req.params['retirementPayId'];
  if (typeof id !== 'string' || !/^\d+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '퇴직금 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function checkAmount(v: unknown, label: string): void {
  if (isBlank(v)) {
    return;
  }
  const ok = (typeof v === 'number' && Number.isFinite(v))
    || (typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)));
  if (!ok || Number(v) < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 0 이상의 숫자여야 합니다.');
  }
}

@Controller('api/v1')
export class FnSfr02306Controller {
  @Get('/retirement-pays/:retirementPayId')
  async getRetirementPay(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT rp.retirement_pay_id AS "retirementPayId",
                e.name AS "employeeName",
                rp.retirement_date AS "retirementDate",
                rp.calculated_amount AS "calculatedAmount",
                rp.withholding_tax AS "withholdingTax",
                rp.confirmed AS "confirmed"
           FROM retirement_pay rp
           JOIN employee e ON e.employee_id = rp.employee_id
          WHERE rp.retirement_pay_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'RETIREMENT_PAY_NOT_FOUND', '영수증 대상이 없습니다.');
      }
      return rows[0];
    });
  }

  @Patch('/retirement-pays/:retirementPayId')
  async updateRetirementPay(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    const data = checks.inputOf(req.body);
    const retirementDate = isBlank(data['retirementDate']) ? null : String(data['retirementDate']);
    if (retirementDate !== null && !/^\d{4}-\d{2}-\d{2}$/.test(retirementDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    checkAmount(data['calculatedAmount'], '퇴직금 산정액');
    checkAmount(data['withholdingTax'], '원천징수세액');
    const calculatedAmount = isBlank(data['calculatedAmount']) ? null : String(data['calculatedAmount']);
    const withholdingTax = isBlank(data['withholdingTax']) ? null : String(data['withholdingTax']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT confirmed AS "confirmed"
           FROM retirement_pay
          WHERE retirement_pay_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RETIREMENT_PAY_NOT_FOUND', '영수증 대상이 없습니다.');
      }
      if (found[0]['confirmed'] === true) {
        throw new ApiError(409, 'RETIREMENT_PAY_ALREADY_CONFIRMED', '확정된 영수증은 수정할 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE retirement_pay
            SET retirement_date = COALESCE(CAST(:retirementDate AS date), retirement_date),
                calculated_amount = COALESCE(CAST(:calculatedAmount AS numeric), calculated_amount),
                withholding_tax = COALESCE(CAST(:withholdingTax AS numeric), withholding_tax),
                updated_at = now()
          WHERE retirement_pay_id = CAST(:id AS bigint)
        RETURNING retirement_pay_id AS "retirementPayId"`,
        { id, retirementDate, calculatedAmount, withholdingTax },
      );
      return rows[0];
    });
  }

  @Post('/retirement-pays/:retirementPayId/confirm')
  @HttpCode(200)
  async confirmRetirementPay(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT confirmed AS "confirmed"
           FROM retirement_pay
          WHERE retirement_pay_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RETIREMENT_PAY_NOT_FOUND', '영수증 대상이 없습니다.');
      }
      if (found[0]['confirmed'] === true) {
        throw new ApiError(409, 'RETIREMENT_PAY_ALREADY_CONFIRMED', '이미 확정된 영수증입니다.');
      }
      const rows = await db.query(
        `UPDATE retirement_pay
            SET confirmed = true,
                updated_at = now()
          WHERE retirement_pay_id = CAST(:id AS bigint)
        RETURNING retirement_pay_id AS "retirementPayId", confirmed AS "confirmed"`,
        { id },
      );
      return rows[0];
    });
  }
}

