import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

function DetailDrawer({ id, role, notify, onClose, onChanged }: {
  id: number;
  role: string;
  notify: (text: string) => void;
  onClose: () => void;
  onChanged: () => void;
}) {
  const detail = useData<Row>(() => call('GET', '/retirement-pays/' + id, role), [id]);
  const [editing, setEditing] = useState(false);
  const [retirementDate, setRetirementDate] = useState('');
  const [calculatedAmount, setCalculatedAmount] = useState<number | string>('');
  const [withholdingTax, setWithholdingTax] = useState<number | string>('');
  const row = detail.data;
  const confirmed = row ? row['confirmed'] === true : false;

  function startEdit() {
    if (!row) {
      return;
    }
    setRetirementDate(String(row['retirementDate'] ?? ''));
    setCalculatedAmount(row['calculatedAmount'] === null || row['calculatedAmount'] === undefined ? '' : Number(row['calculatedAmount']));
    setWithholdingTax(row['withholdingTax'] === null || row['withholdingTax'] === undefined ? '' : Number(row['withholdingTax']));
    setEditing(true);
  }

  async function save() {
    if (!retirementDate) {
      throw new Error('퇴직일을 입력하세요.');
    }
    await call('PATCH', '/retirement-pays/' + id, role, {
      retirementDate,
      calculatedAmount,
      withholdingTax,
    });
    notify('수정했습니다.');
    setEditing(false);
    detail.reload();
    onChanged();
  }

  async function confirm() {
    await call('POST', '/retirement-pays/' + id + '/confirm', role, {});
    notify('확정했습니다.');
    detail.reload();
    onChanged();
  }

  return (
    <Drawer title="퇴직소득 원천징수영수증" onClose={onClose}>
      {detail.error ? <ErrorText text={detail.error} /> : null}
      {row && !editing ? (
        <>
          <Pairs
            items={[
              ['퇴직금 ID', String(row['retirementPayId'])],
              ['성명', String(row['employeeName'] ?? '')],
              ['퇴직일', <DateText value={row['retirementDate']} />],
              ['퇴직금 산정액', <Num value={row['calculatedAmount']} />],
              ['원천징수세액', <Num value={row['withholdingTax']} />],
              ['확정 여부', <Badge value={confirmed ? '확정' : '미확정'} />],
            ]}
          />
          {!confirmed ? (
            <>
              <button type="button" onClick={startEdit}>수정</button>
              <Form onSubmit={confirm} submit="확정" note="확정하면 내용을 수정할 수 없습니다." />
            </>
          ) : null}
        </>
      ) : null}
      {row && editing ? (
        <Form onSubmit={save} submit="저장">
          <Field label="퇴직일" required>
            <DateInput value={retirementDate} onChange={setRetirementDate} />
          </Field>
          <Field label="퇴직금 산정액">
            <NumberInput value={calculatedAmount} onChange={setCalculatedAmount} />
          </Field>
          <Field label="원천징수세액">
            <NumberInput value={withholdingTax} onChange={setWithholdingTax} />
          </Field>
        </Form>
      ) : null}
    </Drawer>
  );
}

function CreateDrawer({ role, notify, onClose, onChanged }: {
  role: string;
  notify: (text: string) => void;
  onClose: () => void;
  onChanged: () => void;
}) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [retirementDate, setRetirementDate] = useState('');

  async function submit() {
    if (employeeId === '' || !retirementDate) {
      throw new Error('퇴직 임직원과 퇴직일을 입력하세요.');
    }
    await call('POST', '/retirement-pays', role, { employeeId, retirementDate });
    notify('퇴직금을 산정했습니다.');
    onChanged();
    onClose();
  }

  return (
    <Drawer title="퇴직금 산정" onClose={onClose}>
      <Form onSubmit={submit} submit="산정">
        <Field label="퇴직 임직원" required>
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
        <Field label="퇴직일" required>
          <DateInput value={retirementDate} onChange={setRetirementDate} />
        </Field>
      </Form>
    </Drawer>
  );
}

export default function FnSfr02306Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [confirmedFilter, setConfirmedFilter] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [creating, setCreating] = useState(false);

  const list = useData<Page>(
    () => call<Page>('GET', '/retirement-pays', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const pending = rows.filter((r) => r['confirmed'] !== true);

  function search() {
    setPage(0);
    setApplied({ employeeId, confirmed: confirmedFilter });
  }

  function reset() {
    setEmployeeId('');
    setConfirmedFilter('');
    setPage(0);
    setApplied({});
  }

  const columns: Column[] = [
    { key: 'retirementPayId', label: '퇴직금 ID' },
    { key: 'employeeId', label: '퇴직 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
    { key: 'calculatedAmount', label: '퇴직금 산정액', render: (r) => <Num value={r['calculatedAmount']} /> },
    { key: 'confirmed', label: '확정 여부', render: (r) => <Badge value={r['confirmed'] === true ? '확정' : '미확정'} /> },
  ];

  const pendingColumns: Column[] = [
    { key: 'employeeId', label: '퇴직 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
  ];

  function open(row: Row) {
    setSelectedId(Number(row['retirementPayId']));
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 건수</h2>
        <Tiles items={[['산정 건수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>확정 대기</h2>
        <Tiles items={[['이 쪽의 미확정', <Num value={pending.length} />]]} />
      </section>
      <section className="box span-8">
        <h2>영수증 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="퇴직 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="확정 여부">
            <Select
              value={confirmedFilter}
              onChange={setConfirmedFilter}
              options={[['true', '확정'], ['false', '미확정']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => setCreating(true)}>퇴직금 산정</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={rows} onRowClick={open} empty="조회된 영수증이 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable columns={pendingColumns} rows={pending} onRowClick={open} empty="확정 대기 건이 없습니다." />
      </section>
      {selectedId !== null ? (
        <DetailDrawer
          id={selectedId}
          role={role}
          notify={notify}
          onClose={() => setSelectedId(null)}
          onChanged={list.reload}
        />
      ) : null}
      {creating ? (
        <CreateDrawer
          role={role}
          notify={notify}
          onClose={() => setCreating(false)}
          onChanged={list.reload}
        />
      ) : null}
    </div>
  );
}
